counterexample:
INSERT INTO t3 (c1, c2) VALUES ('a', 'val_a');
INSERT INTO t3 (c1, c2) VALUES ('b', 'val_b');

INSERT INTO t1 (c1, c2) VALUES ('p', 'dummy_p');

INSERT INTO t2 (c1, c2) VALUES ('r', 'dummy_r');

-- For t3 row 'b', we create a matching t4 row and a t5 row so that the subquery returns a row
INSERT INTO t4 (c1, c2, c3) VALUES ('b', 'p', 1);
INSERT INTO t5 (c1, c2, c3) VALUES ('p', 'r', 1.00);

-- We do not add any row for t6, leaving the subquery (SELECT c2 FROM t6 WHERE c1 = t3.c1) empty for both 'a' and 'b'.
-- This results in the following:
-- For t3 row 'a': no matching t4/t5 row exists, so NOT EXISTS returns true and Q1 returns 'a', while EXISTS returns false in Q2.
-- For t3 row 'b': the matching join returns a row (since 'r' is not in t6 for 'b'), so EXISTS is true and Q2 returns 'b', while Q1 does not return it.

