counterexample:
-- Insert rows for t1: needed for t4 (c2) since t4.c2 references t1(c1)
INSERT INTO t1 (c1, c2) VALUES ('A1', 'dummy1');
INSERT INTO t1 (c1, c2) VALUES ('A2', 'dummy2');

-- Insert row for t2: needed for t5 (c2) since t5.c2 references t2(c1)
INSERT INTO t2 (c1, c2) VALUES ('T2X', 'dummyT2');

-- Insert row for t3: needed for t4 (c1) since t4.c1 references t3(c1)
-- Note: We deliberately insert 'B1' which does not satisfy the condition d.c1 LIKE 'C%'.
INSERT INTO t3 (c1, c2) VALUES ('B1', 'dummy3');

-- Insert rows for t4: these rows link t5 rows via their c1 values
-- Here, f.c1 = 'B1' (which matches 'B%') and f.c2 takes values 'A1' and 'A2'
INSERT INTO t4 (c1, c2, c3) VALUES ('B1', 'A1', 10);
INSERT INTO t4 (c1, c2, c3) VALUES ('B1', 'A2', 20);

-- Insert rows for t5: two rows with same t5.c2 but with c1 values that match the f.c2 values in t4
INSERT INTO t5 (c1, c2, c3) VALUES ('A1', 'T2X', 100.00);
INSERT INTO t5 (c1, c2, c3) VALUES ('A2', 'T2X', 200.00);

