counterexample:
INSERT INTO t2(c1, c2) VALUES ('beer1', 'dummy');

-- Since t5.c1 is a foreign key referencing t1, we must insert corresponding rows in t1
INSERT INTO t1(c1, c2) VALUES ('a', 'dummy'), ('b', 'dummy'), ('c', 'dummy');

-- Insert t5 rows. Note: t5.c2 in each row refers to an entry in t2 (here, 'beer1').
-- Two rows have the minimal price 1.00 and one row has a higher price 2.00.
INSERT INTO t5(c1, c2, c3) VALUES 
  ('a', 'beer1', 1.00),
  ('b', 'beer1', 1.00),
  ('c', 'beer1', 2.00);

